/// pagination: Full and compact
private struct PaginationExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var page = 5

    private func pageButton(_ label: String) -> some View {
        let isCurrent = String(page) == label
        return Button { page = Int(label) ?? page } label: {
            Text(label)
                .monarchTextStyle(.label)
                .foregroundStyle(isCurrent ? theme.colors.accentStrong : theme.colors.textMuted)
                .frame(minWidth: 36, minHeight: 36)
                .background(
                    isCurrent ? theme.colors.accentSubtle : Color.clear,
                    in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                )
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel(label)
        .accessibilityAddTraits(isCurrent ? .isSelected : [])
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack(spacing: 4) {
                MonarchButton("Previous page", systemImage: "chevron.left", variant: .ghost, size: .sm, isIconOnly: true) { page = max(1, page - 1) }
                pageButton("1")
                Text("…").monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
                pageButton("4")
                pageButton("5")
                pageButton("6")
                Text("…").monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
                pageButton("20")
                MonarchButton("Next page", systemImage: "chevron.right", variant: .ghost, size: .sm, isIconOnly: true) { page += 1 }
            }
            HStack(spacing: 4) {
                Text("81–100 of 143").monarchTextStyle(.bodySmall).monospacedDigit().foregroundStyle(theme.colors.textMuted)
                    .padding(.trailing, 8)
                MonarchButton("Previous page", systemImage: "chevron.left", variant: .ghost, size: .sm, isIconOnly: true) { page = max(1, page - 1) }
                MonarchButton("Next page", systemImage: "chevron.right", variant: .ghost, size: .sm, isIconOnly: true) { page += 1 }
            }
        }
    }
}

/// rook-rail: Collapsed, with Help & support and a theme toggle
private struct RookRailExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var current: String? = "calendar"
    @State private var showsSupport = false

    /// One icon button of the rail: named for VoiceOver, with a dot when something is new, and a dark plate and a bar when current.
    private func railButton(_ label: String, systemImage: String, key: String? = nil, hasDot: Bool = false, unread: Int? = nil, hint: String? = nil, action: @escaping () -> Void = {}) -> some View {
        Button {
            if let key { current = key }
            action()
        } label: {
            Image(systemName: systemImage)
                .foregroundStyle(theme.colors.accentOnSolid)
                .frame(width: 40, height: 40)
                .overlay(alignment: .topTrailing) {
                    if hasDot {
                        Circle().fill(theme.colors.accentOnSolid).frame(width: 8, height: 8)
                    }
                }
                .background {
                    if key != nil && current == key {
                        RoundedRectangle(cornerRadius: 8, style: .continuous).fill(theme.colors.accentSolidActive)
                    }
                }
                .overlay(alignment: .leading) {
                    if key != nil && current == key {
                        Capsule().fill(theme.colors.accentOnSolid).frame(width: 3, height: 24).offset(x: -2)
                    }
                }
                .frame(minWidth: 44, minHeight: 44)
        }
        .buttonStyle(.plain)
        .accessibilityLabel(label)
        .accessibilityValue(unread.map { "\($0) unread" } ?? "")
        .accessibilityHint(hint ?? "")
        .accessibilityAddTraits(key != nil && current == key ? .isSelected : [])
    }

    var body: some View {
        HStack(spacing: 0) {
            VStack(spacing: theme.spacing.space1) {
                Text("R")
                    .monarchTextStyle(.bodyStrong)
                    .foregroundStyle(theme.colors.accentOnSolid)
                    .frame(width: 32, height: 32)
                    .background(theme.colors.accentOnSolid.opacity(0.2), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                    .accessibilityLabel("Acme Planner")
                railButton("Home", systemImage: "house", key: "home")
                railButton("Inbox", systemImage: "tray", key: "inbox", hasDot: true, unread: 4)
                railButton("Calendar", systemImage: "calendar", key: "calendar")
                Rectangle().fill(theme.colors.accentOnSolid.opacity(0.25)).frame(height: 1).padding(.horizontal, theme.spacing.space2)
                railButton("Help & support", systemImage: "lifepreserver", hasDot: true, unread: 1) { showsSupport = true }
                railButton("Members", systemImage: "person.2")
                railButton("Settings", systemImage: "gearshape", hint: "Opens in " + "Rook ID")
                railButton("Billing", systemImage: "creditcard", hint: "Opens in " + "Rook ID")
