/// sidebar-nav: Sections, nested groups and badges
private struct SidebarNavExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var selection: String?
    @State private var isDesignOpen = false
    @State private var isResearchOpen = false

    private func row(_ title: String, systemImage: String, tag: String, badge: Int? = nil) -> some View {
        Button {
            selection = tag
        } label: {
            HStack(spacing: theme.spacing.space2) {
                Image(systemName: systemImage).frame(width: 20)
                Text(title)
                Spacer(minLength: 0)
                if let badge {
                    MonarchBadge(String(badge), tone: .accent, variant: .solid, size: .sm)
                }
            }
            .monarchTextStyle(.label)
            .foregroundStyle(selection == tag ? theme.colors.textDefault : theme.colors.textMuted)
            .padding(.horizontal, theme.spacing.space2)
            .frame(minHeight: 44)
            .background(selection == tag ? theme.colors.accentSubtle : Color.clear, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(selection == tag ? .isSelected : [])
    }

    private func group(_ title: String, isOpen: Binding<Bool>, items: [(String, Int?, MonarchTone)], tag: String) -> some View {
        VStack(spacing: 0) {
            Button {
                isOpen.wrappedValue.toggle()
            } label: {
                HStack(spacing: theme.spacing.space2) {
                    Image(systemName: "person.2").frame(width: 20)
                    Text(title)
                    Spacer(minLength: 0)
                    Image(systemName: isOpen.wrappedValue ? "chevron.down" : "chevron.right")
                        .foregroundStyle(theme.colors.textMuted)
                }
                .monarchTextStyle(.label)
                .foregroundStyle(theme.colors.textMuted)
                .padding(.horizontal, theme.spacing.space2)
                .frame(minHeight: 44)
            }
            .buttonStyle(.plain)
            .accessibilityValue(isOpen.wrappedValue ? "Expanded" : "Collapsed")
            if isOpen.wrappedValue {
                ForEach(items, id: \.0) { item in
                    HStack {
                        Text(item.0)
                        Spacer(minLength: 0)
                        if let count = item.1 {
                            MonarchBadge(String(count), tone: item.2, size: .sm)
                        }
                    }
                    .monarchTextStyle(.label)
                    .foregroundStyle(theme.colors.textMuted)
                    .padding(.leading, theme.spacing.space8)
                    .padding(.trailing, theme.spacing.space2)
                    .frame(minHeight: 44)
                }
            }
        }
    }

    private func sectionLabel(_ title: String) -> some View {
        Text(title.uppercased())
            .monarchTextStyle(.caption)
            .foregroundStyle(theme.colors.textMuted)
            .padding(.horizontal, theme.spacing.space2)
            .padding(.top, theme.spacing.space3)
            .accessibilityAddTraits(.isHeader)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            row("Home", systemImage: "house", tag: "home")
            row("Inbox", systemImage: "tray", tag: "inbox", badge: 4)
            row("Calendar", systemImage: "calendar", tag: "calendar")
            sectionLabel("Teams")
            group("Design", isOpen: $isDesignOpen, items: [("Issues", 12, .neutral), ("Backlog", 48, .neutral)], tag: "design")
            group("Research", isOpen: $isResearchOpen, items: [("Issues", nil, .neutral), ("Notes", nil, .neutral)], tag: "research")
            sectionLabel("Workspace")
            row("Settings", systemImage: "gearshape", tag: "settings")
            MonarchDivider().padding(.top, theme.spacing.space8)
            Button {} label: {
                HStack(spacing: theme.spacing.space2) {
                    Image(systemName: "sidebar.left").frame(width: 20)
                    Text("Collapse sidebar")
                }
                .monarchTextStyle(.label)
                .foregroundStyle(theme.colors.textMuted)
                .padding(.horizontal, theme.spacing.space2)
                .frame(minHeight: 44)
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal)
    }
}

