/// top-nav: Wide
private struct TopNavExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var tab = "overview"

    private struct NavLink: Identifiable {
        let key: String
        let label: String
        let badge: Int?
        var id: String { key }
    }

    private static let links = [
        NavLink(key: "overview", label: "Overview", badge: nil),
        NavLink(key: "projects", label: "Projects", badge: 3),
        NavLink(key: "calendar", label: "Calendar", badge: nil),
        NavLink(key: "reports", label: "Reports", badge: nil),
        NavLink(key: "people", label: "People", badge: nil),
        NavLink(key: "settings", label: "Settings", badge: nil),
    ]

    /// The links that fit stay in the row; the rest are in the More menu, so no link is clipped.
    @ViewBuilder private func links(showing count: Int) -> some View {
        HStack(spacing: theme.spacing.space1) {
            ForEach(Self.links.prefix(count)) { link in
                Button {
                    tab = link.key
                } label: {
                    HStack(spacing: theme.spacing.space1_5) {
                        Text(link.label)
                        if let badge = link.badge {
                            Text(verbatim: String(badge))
                                .monarchTextStyle(.caption)
                                .foregroundStyle(theme.colors.dangerOnSolid)
                                .padding(.horizontal, 7)
                                .background(theme.colors.dangerSolid, in: Capsule())
                        }
                    }
                    .monarchTextStyle(.label)
                    .foregroundStyle(tab == link.key ? theme.colors.accentStrong : theme.colors.textMuted)
                    .padding(.horizontal, theme.spacing.space3)
                    .frame(minHeight: 44)
                    .background(tab == link.key ? theme.colors.accentSubtle : Color.clear, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                }
                .buttonStyle(.plain)
                .accessibilityAddTraits(tab == link.key ? .isSelected : [])
            }
            Menu {
                ForEach(Self.links.dropFirst(count)) { link in
                    Button(link.label) { tab = link.key }
                }
            } label: {
                HStack(spacing: theme.spacing.space1) {
                    Text("More")
                    Image(systemName: "chevron.down")
                }
                .monarchTextStyle(.label)
                .foregroundStyle(theme.colors.textMuted)
                .padding(.horizontal, theme.spacing.space3)
                .frame(minHeight: 44)
            }
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            HStack(spacing: theme.spacing.space2) {
                Text("R")
                    .monarchTextStyle(.bodyStrong)
                    .foregroundStyle(theme.colors.textDefault)
                    .frame(width: 28, height: 28)
                    .background(theme.colors.bgMuted, in: RoundedRectangle(cornerRadius: 6, style: .continuous))
                    .accessibilityHidden(true)
                ViewThatFits(in: .horizontal) {
                    links(showing: 4)
                    links(showing: 3)
                    links(showing: 2)
                    links(showing: 1)
                    links(showing: 0)
                }
                Spacer(minLength: 0)
                MonarchButton("Share", variant: .secondary, size: .sm) {}
            }
            Text("Current: /" + (tab == "overview" ? "" : tab)).monarchTextStyle(.caption)
        }
        .padding(.horizontal)
    }
}
